        internal static bool TryGetCoordinateReference(int srid, out EpsgCoordinateReferenceRecord reference, out int cacheIndex)
        {
            switch (srid)
            {
                case 2000:
                    cacheIndex = 0;
                    if (!CoordinateReferences.TryGetValue(0, out reference))
                    {
                        lock (CoordinateReferencesSync)
                        {
                            if (!CoordinateReferences.TryGetValue(0, out reference))
                            {
                                reference = new EpsgCoordinateReferenceRecord(2000, (EpsgCoordinateSystemKind)2, 0);
                                CoordinateReferences[0] = reference;
                            }
                        }
                    }
                    return true;
                case 2001:
                    cacheIndex = 1;
                    if (!CoordinateReferences.TryGetValue(1, out reference))
                    {
                        lock (CoordinateReferencesSync)
                        {
                            if (!CoordinateReferences.TryGetValue(1, out reference))
                            {
