                                CoordinateReferences[1] = reference;
                            }
                        }
                    }
                    return true;
                case 2002:
                    cacheIndex = 2;
                    if (!CoordinateReferences.TryGetValue(2, out reference))
                    {
                        lock (CoordinateReferencesSync)
                        {
                            if (!CoordinateReferences.TryGetValue(2, out reference))
                            {
                                reference = new EpsgCoordinateReferenceRecord(2002, (EpsgCoordinateSystemKind)2, 2);
                                CoordinateReferences[2] = reference;
                            }
                        }
                    }
                    return true;
